#include "document.hpp"
#include <algorithm>
#include <set>
#include "bridge.hpp"

namespace blitz::lsp {
	std::string lower(std::string_view text)
	{
		return tools::lower(text);
	}

	namespace {
		// The UTF-16 length of the UTF-8 sequence that starts with this byte.
		size_t sequence_length(unsigned char lead)
		{
			if (lead < 0x80) return 1;
			if ((lead >> 5) == 0x6) return 2;
			if ((lead >> 4) == 0xE) return 3;
			if ((lead >> 3) == 0x1E) return 4;
			return 1;
		}
	} // namespace

	document::document(std::string source)
	{
		set_text(std::move(source));
	}

	void document::set_text(std::string source)
	{
		text = std::move(source);
		build();
	}

	void document::build()
	{
		_starts.assign(1, 0);
		for (size_t i = 0; i < text.size(); i++) {
			if (text[i] == '\n') {
				_starts.push_back(i + 1);
			} else if (text[i] == '\r') {
				if (i + 1 < text.size() && text[i + 1] == '\n') i++;
				_starts.push_back(i + 1);
			}
		}
		_tokens = tools::tokenize(text);
		_offsets.clear();
		_words.clear();
		size_t at = 0;
		for (size_t i = 0; i < _tokens.size(); i++) {
			_offsets.push_back(at);
			auto const& t = _tokens[i];
			if (t.is(tools::kind::word)) {
				word w;
				w.begin = at;
				w.end = at + t.text.size();
				size_t core = t.text.size();
				while (core > 1 && (t.text[core - 1] == '%' || t.text[core - 1] == '#' || t.text[core - 1] == '$')) core--;
				w.core_end = at + core;
				w.text = t.text;
				w.name = lower(t.text.substr(0, core));
				w.token = i;
				_words.push_back(std::move(w));
			}
			at += t.text.size();
		}
	}

	size_t document::to_offset(position p) const
	{
		if (p.line >= _starts.size()) return text.size();
		size_t at  = _starts[p.line];
		size_t end = (p.line + 1 < _starts.size()) ? _starts[p.line + 1] : text.size();
		uint32_t units = 0;
		while (at < end && units < p.character) {
			if (text[at] == '\n' || text[at] == '\r') break;
			size_t len = sequence_length(static_cast<unsigned char>(text[at]));
			units += (len == 4) ? 2 : 1;
			at += len;
		}
		return std::min(at, text.size());
	}

	position document::to_position(size_t offset) const
	{
		offset = std::min(offset, text.size());
		auto it   = std::upper_bound(_starts.begin(), _starts.end(), offset);
		size_t line = size_t(it - _starts.begin()) - 1;
		uint32_t units = 0;
		for (size_t at = _starts[line]; at < offset;) {
			size_t len = sequence_length(static_cast<unsigned char>(text[at]));
			units += (len == 4) ? 2 : 1;
			at += len;
		}
		return position{ uint32_t(line), units };
	}

	size_t document::offset_of(uint64_t line, uint64_t column) const
	{
		if (line == 0) return 0;
		if (line > _starts.size()) return text.size();
		size_t at = _starts[line - 1] + (column > 0 ? size_t(column - 1) : 0);
		size_t end = (line < _starts.size()) ? _starts[line] : text.size();
		return std::min(at, end);
	}

	range document::to_range(size_t begin, size_t end) const
	{
		return range{ to_position(begin), to_position(end) };
	}

	word const* document::word_at(size_t offset) const
	{
		for (auto const& w : _words) {
			if (offset >= w.begin && offset <= w.end) return &w;
			if (w.begin > offset) break;
		}
		return nullptr;
	}

	size_t document::previous_token(size_t token) const
	{
		while (token-- > 0) {
			if (!_tokens[token].is(tools::kind::space)) return token;
		}
		return size_t(-1);
	}

	size_t document::next_token(size_t token) const
	{
		for (size_t i = token + 1; i < _tokens.size(); i++) {
			if (!_tokens[i].is(tools::kind::space)) return i;
		}
		return size_t(-1);
	}

	namespace {
		bool is_word(tools::token const& t, const char* keyword)
		{
			return t.is(tools::kind::word) && lower(t.text) == keyword;
		}
	} // namespace

	bool document::function_at(size_t offset, size_t& begin, size_t& end, std::string* name) const
	{
		bool inside = false;
		for (size_t i = 0; i < _tokens.size(); i++) {
			if (!_tokens[i].is(tools::kind::word)) continue;
			auto l = lower(_tokens[i].text);
			if (l == "function") {
				// A line that starts with Function (the word may also be a `Function` field name, which a backslash would precede).
				size_t p = previous_token(i);
				if (p != size_t(-1) && _tokens[p].is_symbol("\\")) continue;
				if (_offsets[i] > offset && inside) return false;
				begin  = _offsets[i];
				end    = text.size();
				inside = true;
				if (name) {
					size_t n = next_token(i);
					*name = (n != size_t(-1)) ? lower(_tokens[n].text) : std::string();
					while (!name->empty() && (name->back() == '%' || name->back() == '#' || name->back() == '$')) name->pop_back();
				}
			} else if ((l == "end" || l == "endfunction") && inside) {
				bool closes = (l == "endfunction");
				if (l == "end") {
					size_t n = next_token(i);
					closes = (n != size_t(-1)) && is_word(_tokens[n], "function");
				}
				if (closes) {
					size_t stop = _offsets[i] + _tokens[i].text.size();
					if (offset >= begin && offset <= stop) {
						end = stop;
						return true;
					}
					inside = false;
				}
			}
		}
		return inside && offset >= begin;
	}

	std::vector<document::declaration> document::declarations_of(std::string const& name) const
	{
		std::vector<declaration> found;
		// Names that follow these words are declared by them; `Local a, b` and `Dim a(1), b(2)` are handled by the list below.
		for (auto const& w : _words) {
			if (w.name != name) continue;
			size_t p = previous_token(w.token);
			if (p == size_t(-1)) continue;
			auto const& before = _tokens[p];
			declaration d;
			d.begin = w.begin;
			d.end   = w.core_end;
			d.scope_begin = 0;
			d.scope_end   = text.size();
			if (before.is(tools::kind::word)) {
				auto l = lower(before.text);
				if (l == "function") d.what = declaration::kind::function;
				else if (l == "type") d.what = declaration::kind::type;
				else if (l == "field") d.what = declaration::kind::field;
				else if (l == "dim") d.what = declaration::kind::dim;
				else if (l == "const") d.what = declaration::kind::constant;
				else if (l == "global") d.what = declaration::kind::variable;
				else if (l == "local") {
					d.what = declaration::kind::variable;
					size_t b, e;
					if (function_at(w.begin, b, e)) { d.scope_begin = b; d.scope_end = e; }
				}
			} else if (before.is_symbol(".")) {
				// A label is `.name` at the start of a line.
				size_t pp = previous_token(p);
				bool start = (pp == size_t(-1)) || _tokens[pp].is(tools::kind::newline) || _tokens[pp].is(tools::kind::separator);
				if (start) d.what = declaration::kind::label;
			} else if (before.is(tools::kind::separator) || before.is_symbol(",")) {
				// `Local a, b`, `Global x, y`, `Const a = 1, b = 2`: walk back over the list to the keyword on the same statement.
				size_t i = p;
				int depth = 0;
				while (i != size_t(-1)) {
					auto const& t = _tokens[i];
					if (t.is(tools::kind::newline)) break;
					if (t.is_symbol(")")) depth++;
					if (t.is_symbol("(")) depth--;
					if (t.is(tools::kind::separator) && depth == 0) break;
					if (t.is(tools::kind::word) && depth == 0) {
						auto l = lower(t.text);
						if (before.is_symbol(",") && (l == "local" || l == "global" || l == "const" || l == "dim")) {
							d.what = (l == "const") ? declaration::kind::constant : (l == "dim" ? declaration::kind::dim : declaration::kind::variable);
							if (l == "local") {
								size_t b, e;
								if (function_at(w.begin, b, e)) { d.scope_begin = b; d.scope_end = e; }
							}
							break;
						}
						if (l == "function") break;
					}
					i = previous_token(i);
				}
			}
			if (d.what != declaration::kind::none) found.push_back(d);
		}
		// Parameters: names inside the parentheses of the Function line.
		for (size_t i = 0; i < _tokens.size(); i++) {
			if (!is_word(_tokens[i], "function")) continue;
			size_t p = previous_token(i);
			if (p != size_t(-1) && _tokens[p].is_symbol("\\")) continue;
			size_t open = i;
			while (open < _tokens.size() && !_tokens[open].is_symbol("(") && !_tokens[open].is(tools::kind::newline)) open++;
			if (open >= _tokens.size() || !_tokens[open].is_symbol("(")) continue;
			size_t b = _offsets[i], e = text.size();
			function_at(b, b, e);
			for (size_t k = open + 1; k < _tokens.size() && !_tokens[k].is(tools::kind::newline) && !_tokens[k].is_symbol(")"); k++) {
				if (!_tokens[k].is(tools::kind::word)) continue;
				size_t pk = previous_token(k);
				bool name_position = (pk == open) || _tokens[pk].is_symbol(",");
				if (!name_position) continue;
				for (auto const& w : _words) {
					if (w.token == k && w.name == name) {
						declaration d;
						d.what = declaration::kind::parameter;
						d.begin = w.begin;
						d.end = w.core_end;
						d.scope_begin = b;
						d.scope_end = e;
						found.push_back(d);
					}
				}
			}
		}
		std::sort(found.begin(), found.end(), [](declaration const& a, declaration const& b) { return a.begin < b.begin; });
		return found;
	}

	std::vector<std::pair<size_t, size_t>> document::rename_targets(size_t offset, std::string& why, std::string const& builtin_hint) const
	{
		std::vector<std::pair<size_t, size_t>> out;
		auto* at = word_at(offset);
		if (!at) {
			why = "There is no name here.";
			return out;
		}
		if (bridge::is_keyword(at->name)) {
			why = "'" + at->text + "' is a keyword.";
			return out;
		}
		if (!builtin_hint.empty()) {
			why = builtin_hint;
			return out;
		}
		const std::string name = at->name;
		size_t p = previous_token(at->token);
		size_t n = next_token(at->token);
		bool after_backslash = (p != size_t(-1)) && _tokens[p].is_symbol("\\");
		bool after_dot = (p != size_t(-1)) && _tokens[p].is_symbol(".");
		bool called = (n != size_t(-1)) && _tokens[n].is_symbol("(");
		auto decls = declarations_of(name);

		auto has = [&](declaration::kind k) {
			return std::any_of(decls.begin(), decls.end(), [&](declaration const& d) { return d.what == k; });
		};
		auto previous_is = [&](size_t token, std::initializer_list<const char*> keywords) {
			size_t q = previous_token(token);
			if (q == size_t(-1) || !_tokens[q].is(tools::kind::word)) return false;
			auto l = lower(_tokens[q].text);
			return std::any_of(keywords.begin(), keywords.end(), [&](const char* k) { return l == k; });
		};

		enum class what { field, type, function, label, variable } role;
		if (after_backslash || previous_is(at->token, { "field" })) {
			role = what::field;
		} else if (previous_is(at->token, { "type", "new", "each", "first", "last" }) || (after_dot && !called)) {
			// `Type Name`, `New Name`, `Each Name`, and `x.Name`; but `.name` at the start of a line is a label.
			size_t pp = (p != size_t(-1)) ? previous_token(p) : size_t(-1);
			bool label = after_dot && (pp == size_t(-1) || _tokens[pp].is(tools::kind::newline) || _tokens[pp].is(tools::kind::separator));
			role = label ? what::label : what::type;
		} else if (previous_is(at->token, { "function" }) || (called && has(declaration::kind::function))) {
			role = what::function;
		} else if (previous_is(at->token, { "goto", "gosub", "restore" })) {
			role = what::label;
		} else if (has(declaration::kind::function) && !has(declaration::kind::variable) && !has(declaration::kind::parameter) && !has(declaration::kind::dim)) {
			role = what::function;
		} else if (!has(declaration::kind::variable) && !has(declaration::kind::parameter) && !has(declaration::kind::constant) && !has(declaration::kind::dim)) {
			// Not declared anywhere: it is an implicit variable, a command of the runtime or a name from an included file.
			role = what::variable;
		} else {
			role = what::variable;
		}

		size_t fb = 0, fe = text.size();
		bool in_function = function_at(offset, fb, fe);
		// A variable is local to the function if one of the declarations in the function is a Local or parameter; otherwise it is global.
		bool local = false;
		if (role == what::variable && in_function) {
			for (auto const& d : decls) {
				if ((d.what == declaration::kind::parameter || (d.what == declaration::kind::variable && d.scope_begin != 0)) && d.scope_begin == fb) local = true;
			}
			if (!local) {
				// Without any declaration the name is a local of this function unless some Global of that name exists.
				bool global = std::any_of(decls.begin(), decls.end(), [](declaration const& d) { return d.scope_begin == 0 && (d.what == declaration::kind::variable || d.what == declaration::kind::constant || d.what == declaration::kind::dim); });
				local = !global;
			}
		}
		if (role == what::variable && !in_function) {
			// Main program: functions' own locals are not the same variable.
		}

		for (auto const& w : _words) {
			if (w.name != name) continue;
			size_t wp = previous_token(w.token);
			size_t wn = next_token(w.token);
			bool w_backslash = (wp != size_t(-1)) && _tokens[wp].is_symbol("\\");
			bool w_dot = (wp != size_t(-1)) && _tokens[wp].is_symbol(".");
			bool w_called = (wn != size_t(-1)) && _tokens[wn].is_symbol("(");
			bool match = false;
			switch (role) {
			case what::field:
				match = w_backslash || previous_is(w.token, { "field" });
				break;
			case what::type: {
				size_t wpp = (wp != size_t(-1)) ? previous_token(wp) : size_t(-1);
				bool label = w_dot && (wpp == size_t(-1) || _tokens[wpp].is(tools::kind::newline) || _tokens[wpp].is(tools::kind::separator));
				match = previous_is(w.token, { "type", "new", "each", "first", "last" }) || (w_dot && !label);
				break;
			}
			case what::function:
				match = previous_is(w.token, { "function" }) || (w_called && !w_backslash && !w_dot);
				break;
			case what::label: {
				size_t wpp = (wp != size_t(-1)) ? previous_token(wp) : size_t(-1);
				bool decl = w_dot && (wpp == size_t(-1) || _tokens[wpp].is(tools::kind::newline) || _tokens[wpp].is(tools::kind::separator));
				match = decl || previous_is(w.token, { "goto", "gosub", "restore" });
				break;
			}
			case what::variable: {
				if (w_backslash) break; // a field with the same name
				if (previous_is(w.token, { "function", "type", "field", "new", "each", "first", "last", "goto", "gosub", "restore" })) break;
				if (w_dot) {
					size_t wpp = (wp != size_t(-1)) ? previous_token(wp) : size_t(-1);
					bool label = (wpp == size_t(-1)) || _tokens[wpp].is(tools::kind::newline) || _tokens[wpp].is(tools::kind::separator);
					if (!label) break; // `x.TypeName`
					break;
				}
				if (w_called && !has(declaration::kind::dim) && has(declaration::kind::function)) break;
				// A type after a colon (x:Name) is a type name, not a variable.
				if (wp != size_t(-1) && _tokens[wp].is(tools::kind::separator) && _tokens[wp].text == ":") {
					size_t adjacent_before = w.begin;
					if (adjacent_before > 0 && text[adjacent_before - 1] == ':' && adjacent_before > 1 && !std::isspace(static_cast<unsigned char>(text[adjacent_before - 2]))) break;
				}
				size_t b2 = 0, e2 = text.size();
				bool w_in_function = function_at(w.begin, b2, e2);
				if (local) {
					match = w_in_function && b2 == fb;
				} else {
					// Global: every use outside of the functions that have a Local or parameter of that name.
					if (!w_in_function) {
						match = true;
					} else {
						bool shadowed = std::any_of(decls.begin(), decls.end(), [&](declaration const& d) { return d.scope_begin == b2 && (d.what == declaration::kind::parameter || d.what == declaration::kind::variable); });
						match = !shadowed;
					}
				}
				break;
			}
			}
			if (match) out.emplace_back(w.begin, w.core_end);
		}
		if (out.empty()) why = "Nothing to rename.";
		return out;
	}

	text_change minimal_change(std::string const& from, std::string const& to)
	{
		text_change c;
		if (from == to) return c;
		size_t start = 0;
		size_t limit = std::min(from.size(), to.size());
		while (start < limit && from[start] == to[start]) start++;
		size_t tail = 0;
		while (tail < limit - start && from[from.size() - 1 - tail] == to[to.size() - 1 - tail]) tail++;
		// Do not cut a UTF-8 sequence in half, at either end.
		while (start > 0 && (start < from.size()) && (static_cast<unsigned char>(from[start]) & 0xC0) == 0x80) start--;
		while (tail > 0 && (from.size() - tail < from.size()) && (static_cast<unsigned char>(from[from.size() - tail]) & 0xC0) == 0x80) tail--;
		c.any = true;
		c.begin = start;
		c.end = from.size() - tail;
		c.replacement = to.substr(start, to.size() - tail - start);
		return c;
	}
} // namespace blitz::lsp
